python3 -c '
import re, sys
try:
    lines = open("release-notes.md", encoding="utf-8").read().splitlines()
except OSError as exc:
    print("release-notes.md unreadable: %s" % exc)
    sys.exit(1)
sections, current = {}, None
for line in lines:
    head = re.sub(r"#+\s*", "# ", line.strip().lower())
    if head.startswith("# "):
        current = head
        sections.setdefault(current, [])
    elif current is not None:
        sections[current].append(line.lower())
feat = ["bundle-budget", "dry-run", "endpoint-index"]
fix = ["notes-tail", "path-escape", "hub-retry"]
feat_body = "\n".join(sections.get("# features", []))
fix_body = "\n".join(sections.get("# fixes", []))
if not feat_body or not fix_body:
    print("need a `## Features` section and a `## Fixes` section with content in them")
    sys.exit(1)
reasons = []
for name, want, other, body in (("Features", feat, fix, feat_body), ("Fixes", fix, feat, fix_body)):
    missing = [w for w in want if w not in body]
    leaked = [w for w in other if w in body]
    if missing:
        reasons.append("%s is missing %s" % (name, ", ".join(missing)))
    if leaked:
        reasons.append("%s carries %s, which belongs in the other section" % (name, ", ".join(leaked)))
for r in reasons:
    print(r)
sys.exit(0 if not reasons else 1)'

