import re, sys
try:
    text = open("story.txt", encoding="utf-8").read().strip()
except OSError as exc:
    print("story.txt unreadable: %s" % exc)
    sys.exit(1)
sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]
want = ["once", "midnight", "later"]
openers = [s.split(" ", 1)[0].strip(",.:;").lower() for s in sentences]
reasons = []
if len(sentences) != 3:
    reasons.append("expected exactly 3 sentences, got %d" % len(sentences))
if openers != want:
    reasons.append("the sentences open with %r, expected %r in that order" % (openers, want))
low = text.lower()
if "lantern" not in low:
    reasons.append("the required word lantern is absent")
if "dragon" in low:
    reasons.append("the forbidden word dragon is present")
for r in reasons:
    print(r)
sys.exit(0 if not reasons else 1)'

